const adminPayslipStatus = (row: { paymentStatus: string; payrollrun: { status: string } }) => row.paymentStatus === "PAID" || ["PAID", "DISBURSED"].includes(row.payrollrun.status) ? "PAID" : row.paymentStatus === "FAILED" ? "FAILED" : row.payrollrun.status === "APPROVED" ? "READY" : "PENDING";
const payslipDateWhere = (query: any) => { if (!query.year && !query.month && !query.quarter) return {}; const year = query.year; const months = query.month ? [query.month] : query.quarter ? Array.from({ length: 3 }, (_, index) => (Number(query.quarter.slice(1)) - 1) * 3 + index + 1) : []; if (year && !months.length) return { periodStart: { gte: new Date(Date.UTC(year, 0, 1)), lt: new Date(Date.UTC(year + 1, 0, 1)) } }; if (year && months.length) return { OR: months.map((month) => ({ periodStart: { gte: new Date(Date.UTC(year, month - 1, 1)), lt: new Date(Date.UTC(year, month, 1)) } })) }; return {};
};
const adminPayslipDto = (row: any) => { const month = row.payrollrun.periodStart.getUTCMonth() + 1; const year = row.payrollrun.periodStart.getUTCFullYear(); return { id: row.id, payRunId: row.payrollRunId, payRunItemId: row.id, employee: { id: row.employeeId, employeeId: row.employeeNoSnapshot ?? row.employee.employeeNo, fullName: row.employeeNameSnapshot ?? `${row.employee.firstName} ${row.employee.lastName}`.trim(), role: row.roleSnapshot ?? row.employee.jobTitle, avatarUrl: row.employee.profileImageUrl }, department: { id: row.departmentIdSnapshot, name: row.departmentNameSnapshot }, period: { label: row.payrollrun.name, month, year }, grossPay: Number(row.grossPay), totalDeductions: Number(row.deductions), netPay: Number(row.netPay), status: adminPayslipStatus(row), availableActions: ["VIEW", "DOWNLOAD"], currency: row.currency }; };
const adminPayslipStatusWhere = (status?: string): Prisma.PayslipWhereInput => {
  if (status === "PAID") return { OR: [{ paymentStatus: "PAID" }, { payrollrun: { status: { in: ["PAID", "DISBURSED"] } } }] };
  if (status === "FAILED") return { paymentStatus: "FAILED" };
  if (status === "READY") return { paymentStatus: { notIn: ["PAID", "FAILED"] }, payrollrun: { status: "APPROVED" } };
  if (status === "PENDING") return { paymentStatus: { notIn: ["PAID", "FAILED"] }, payrollrun: { status: { notIn: ["APPROVED", "PAID", "DISBURSED"] } } };
  return {};
};
export const listAdminPayslips = async (organizationId: string, query: any) => {
  const where: Prisma.PayslipWhereInput = { organizationId, ...(query.departmentId ? { departmentIdSnapshot: query.departmentId } : {}), ...(query.search ? { OR: [{ employeeNameSnapshot: { contains: query.search } }, { employeeNoSnapshot: { contains: query.search } }, { departmentNameSnapshot: { contains: query.search } }] } : {}), payrollrun: payslipDateWhere(query), AND: [adminPayslipStatusWhere(query.status)] };
  const [rows, total, totals, periods, departments] = await Promise.all([
    prisma.payslip.findMany({ where, include: { payrollrun: true, employee: { select: { employeeNo: true, firstName: true, lastName: true, jobTitle: true, profileImageUrl: true } } }, orderBy: [{ payrollrun: { periodStart: "desc" } }, { employeeNameSnapshot: "asc" }], skip: (query.page - 1) * query.limit, take: query.limit }),
    prisma.payslip.count({ where }),
    prisma.payslip.aggregate({ where, _sum: { grossPay: true, deductions: true, netPay: true } }),
    prisma.payrollRun.groupBy({ by: ["periodStart"], where: { organizationId, payslip: { some: {} } }, orderBy: { periodStart: "desc" }, take: 240 }),
    prisma.department.findMany({ where: { organizationId }, select: { id: true, name: true }, orderBy: { name: "asc" }, take: 1000 }),
  ]);
  const items = rows.map(adminPayslipDto);
  return { period: { year: query.year ?? null, quarter: query.quarter ?? null, month: query.month ?? null, label: items[0]?.period.label ?? null }, totals: { payslipCount: total, totalGross: Number(totals._sum.grossPay ?? 0), totalDeductions: Number(totals._sum.deductions ?? 0), totalNetPay: Number(totals._sum.netPay ?? 0) }, filters: { years: [...new Set(periods.map((row) => row.periodStart.getUTCFullYear()))], months: [...new Set(periods.map((row) => row.periodStart.getUTCMonth() + 1))].sort((a, b) => a - b), departments, statuses: ["PAID", "PENDING", "READY", "FAILED"] }, payslips: items, pagination: payeePagination(query.page, query.limit, total) };
};
const tenantPayslip = async (organizationId: string, payslipId: string) => { const row = await prisma.payslip.findFirst({ where: { id: payslipId, organizationId }, include: { payrollrun: true, employee: { select: { employeeNo: true, firstName: true, lastName: true, jobTitle: true, profileImageUrl: true } } } }); if (!row) throw notFound("Payslip not found"); return row; };
