export const evaluateUnifiedPayeeEligibility = (payee: any, start: Date, end: Date) => {
  const reasons: string[] = [];
  if (payee.deletedAt) reasons.push("PAYEE_REMOVED");
  if (!["PERMANENT", "CONTRACT", "CONSULTANT"].includes(payee.type) || payee.taxRegime === "LEGACY_UNSPECIFIED") reasons.push("LEGACY_RECLASSIFICATION_REQUIRED");
  if (payee.type === "PERMANENT") {
    if (payee.taxRegime !== "PAYE") reasons.push("INVALID_TAX_REGIME");
    if (!payee.employee) reasons.push("EMPLOYEE_LINK_REQUIRED");
    else { const employee = payee.employee; if (employee.status !== "ACTIVE") reasons.push("EMPLOYEE_NOT_ACTIVE"); if (employee.lifecycleStatus === "EXITED") reasons.push("EMPLOYEE_EXITED"); if (!employee.hireDate || employee.hireDate > end) reasons.push("STARTS_AFTER_PERIOD"); const enrollment = employee.payrollEnrollment; if (!enrollment || !enrollment.isActive || enrollment.enrolledAt > end || (enrollment.removedAt && enrollment.removedAt <= start)) reasons.push("PAYROLL_ENROLLMENT_INACTIVE"); if (!employee.salaryStructures?.length) reasons.push("SALARY_STRUCTURE_MISSING"); }
  } else if (payee.type === "CONTRACT" || payee.type === "CONSULTANT") {
    if (payee.status !== "ACTIVE") reasons.push("PAYEE_NOT_ACTIVE");
    if (!payee.externalOnPayroll) reasons.push("NOT_ON_PAYROLL");
    if (!payee.name?.trim()) reasons.push("IDENTITY_REQUIRED");
    if (!payee.monthlyAmount || Number(payee.monthlyAmount) <= 0) reasons.push("COMPENSATION_REQUIRED");
    if (payee.taxRegime !== (payee.type === "CONTRACT" ? "WHT" : "EXEMPT")) reasons.push("INVALID_TAX_REGIME");
    if (payee.dateOnboarded && payee.dateOnboarded > start) reasons.push(payee.dateOnboarded <= end ? "STARTS_DURING_PERIOD" : "STARTS_AFTER_PERIOD");
  }
  return [...new Set(reasons)];
};
