const reconcileUnifiedPayRunCompletion = async (payrollRunId: string) => prisma.$transaction(async (tx) => {
  const remaining = await tx.payrollCalculationBatch.count({ where: { payrollRunId, status: { not: "COMPLETED" } } });
  if (remaining) return "PENDING" as const;
  const run = await tx.payrollRun.findUniqueOrThrow({ where: { id: payrollRunId } });
  if (run.status !== "PROCESSING" || run.membershipVersion !== "UNIFIED_PAYEE_V1") return "UNCHANGED" as const;
  const [payslips, external] = await Promise.all([tx.payslip.count({ where: { payrollRunId } }), tx.payeePayment.count({ where: { payrollRunId } })]);
  const reconciled = run.processedParticipantCount === run.participantCount && payslips === run.permanentEmployeeCount && external === run.externalPayeeCount;
  const input = jsonRecord(run.calculationInput);
  if (!reconciled) {
    await tx.payrollRun.updateMany({ where: { id: run.id, status: "PROCESSING" }, data: { status: "FAILED", failureReason: "Frozen payroll processing result reconciliation failed" } });
    await createAuditLog({ organizationId: run.organizationId, actorUserId: typeof input.requestedById === "string" ? input.requestedById : undefined, action: "PAYROLL_RUN_PROCESSING_FAILED", resource: "PAYROLL_RUN", resourceId: run.id, summary: "Frozen unified payroll result reconciliation failed", metadata: { participantCount: run.participantCount, processedParticipantCount: run.processedParticipantCount, expectedPayslips: run.permanentEmployeeCount, actualPayslips: payslips, expectedPayeePayments: run.externalPayeeCount, actualPayeePayments: external, previousStatus: "PROCESSING", newStatus: "FAILED" } }, tx);
    return "FAILED" as const;
  }
  const transitioned = await tx.payrollRun.updateMany({ where: { id: run.id, status: "PROCESSING", processedParticipantCount: { equals: run.participantCount }, failedParticipantCount: 0 }, data: { status: "PENDING_APPROVAL", computedAt: new Date(), failureReason: null } });
  if (transitioned.count) await createAuditLog({ organizationId: run.organizationId, actorUserId: typeof input.requestedById === "string" ? input.requestedById : undefined, action: "PAYROLL_RUN_PROCESSING_COMPLETED", resource: "PAYROLL_RUN", resourceId: run.id, summary: "Completed frozen unified payroll calculation", metadata: { participantCount: run.participantCount, permanentEmployeeCount: run.permanentEmployeeCount, externalPayeeCount: run.externalPayeeCount, previousStatus: "PROCESSING", newStatus: "PENDING_APPROVAL" } }, tx);
  return transitioned.count ? "COMPLETED" as const : "UNCHANGED" as const;
}, { isolationLevel: Prisma.TransactionIsolationLevel.RepeatableRead, maxWait: 20_000, timeout: 60_000 });

export const initializePayRunCalculation = async (payrollRunId: string, options: { execution?: "queue" | "direct"; batchLimit?: number } = {}) => {
  const run = await prisma.payrollRun.findFirst({ where: { id: payrollRunId, status: "PROCESSING" } }); if (!run) return { skipped: true };
  const existing = await prisma.payrollCalculationBatch.count({ where: { payrollRunId } });
  if (!existing) {
    let cursor: string | undefined; let batchIndex = 0; let expected = 0;
    while (true) {
      if (run.membershipVersion === "UNIFIED_PAYEE_V1") {
        const participants = await prisma.payrollRunParticipant.findMany({ where: { organizationId: run.organizationId, payrollRunId, frozenAt: { not: null } }, orderBy: { id: "asc" }, take: payrollBatchSize, ...(cursor ? { cursor: { id: cursor }, skip: 1 } : {}), select: { id: true } });
        if (!participants.length) break;
        await prisma.payrollCalculationBatch.upsert({ where: { payrollRunId_batchIndex: { payrollRunId, batchIndex } }, create: { organizationId: run.organizationId, payrollRunId, batchIndex, employeeIds: [], participantIds: participants.map((participant) => participant.id), expectedCount: participants.length }, update: {} });
        expected += participants.length; batchIndex += 1; cursor = participants.at(-1)!.id;
        if (participants.length < payrollBatchSize) break;
      } else {
        const employees = await prisma.employee.findMany({ where: payRunEmployeeWhere(run.organizationId, run.periodStart, run.periodEnd), orderBy: { id: "asc" }, take: payrollBatchSize, ...(cursor ? { cursor: { id: cursor }, skip: 1 } : {}), select: { id: true } });
        if (!employees.length) break;
        await prisma.payrollCalculationBatch.upsert({ where: { payrollRunId_batchIndex: { payrollRunId, batchIndex } }, create: { organizationId: run.organizationId, payrollRunId, batchIndex, employeeIds: employees.map((employee) => employee.id), expectedCount: employees.length }, update: {} });
        expected += employees.length; batchIndex += 1; cursor = employees.at(-1)!.id;
        if (employees.length < payrollBatchSize) break;
      }
    }
    if (!expected) { await prisma.payrollRun.update({ where: { id: payrollRunId }, data: { status: "FAILED", failureReason: run.membershipVersion === "UNIFIED_PAYEE_V1" ? "Frozen participant set is empty" : "No eligible employees are configured for this payroll period" } }); return { failed: true }; }
    if (run.membershipVersion === "UNIFIED_PAYEE_V1" && expected !== run.participantCount) { await prisma.payrollRun.update({ where: { id: payrollRunId }, data: { status: "FAILED", failureReason: "Frozen participant set does not match the claimed participant count" } }); return { failed: true }; }
    await prisma.payrollRun.update({ where: { id: payrollRunId }, data: run.membershipVersion === "UNIFIED_PAYEE_V1" ? { processingHeartbeatAt: new Date() } : { expectedEmployeeCount: expected, employeeCount: expected, processingHeartbeatAt: new Date() } });
  }
  const batches = await prisma.payrollCalculationBatch.findMany({ where: { payrollRunId, status: "PENDING" }, orderBy: { batchIndex: "asc" }, take: options.batchLimit, select: { id: true } });
  if (run.membershipVersion === "UNIFIED_PAYEE_V1" && existing > 0 && !batches.length) return { reconciliation: await reconcileUnifiedPayRunCompletion(payrollRunId) };
  if (options.execution === "direct") {
    const results = [];
    for (const batch of batches) results.push(await processPayRunBatch(batch.id));
    return { processedBatches: results.length };
  }
  await Promise.all(batches.map((batch) => enqueuePayrollJob("calculate-payroll-batch", { batchId: batch.id }, `payroll-batch-${batch.id}`)));
  return { queuedBatches: batches.length };
};

export const processPayRunBatch = async (batchId: string) => {
  const claimed = await prisma.payrollCalculationBatch.updateMany({ where: { id: batchId, status: "PENDING" }, data: { status: "PROCESSING", attempts: { increment: 1 }, startedAt: new Date(), errorMessage: null } }); if (!claimed.count) return { skipped: true };
  const batch = await prisma.payrollCalculationBatch.findUniqueOrThrow({ where: { id: batchId }, include: { payrollRun: true } });
  try {
    const unified = batch.payrollRun.membershipVersion === "UNIFIED_PAYEE_V1";
    const employeeIds = Array.isArray(batch.employeeIds) ? batch.employeeIds.filter((id): id is string => typeof id === "string") : [];
    const participantIds = Array.isArray(batch.participantIds) ? batch.participantIds.filter((id): id is string => typeof id === "string") : [];
    const input = jsonRecord(batch.payrollRun.calculationInput); const currency = typeof input.currency === "string" ? input.currency : "NGN";
    const computed = await prisma.$transaction(async (tx) => {
      if (unified) {
        if (participantIds.length !== batch.expectedCount) throw conflict("Payroll batch participant count is inconsistent");
        const totals = await computeFrozenParticipantResults(tx, batch, participantIds);
        const completed = await tx.payrollCalculationBatch.updateMany({ where: { id: batch.id, status: "PROCESSING" }, data: { status: "COMPLETED", processedCount: totals.participants, failedCount: 0, totals: { participants: totals.participants, permanent: totals.permanent, external: totals.external, gross: totals.gross.toString(), paye: totals.paye.toString(), wht: totals.wht.toString(), pension: totals.pension.toString(), employerPension: totals.employerPension.toString(), nhf: totals.nhf.toString(), loans: totals.loans.toString(), other: totals.other.toString(), permanentNet: totals.permanentNet.toString(), externalNet: totals.externalNet.toString(), net: totals.net.toString() }, completedAt: new Date() } });
        if (completed.count) await tx.payrollRun.update({ where: { id: batch.payrollRunId }, data: { processedParticipantCount: { increment: totals.participants }, processedEmployeeCount: { increment: totals.permanent }, totalGross: { increment: totals.gross }, totalPaye: { increment: totals.paye }, totalWht: { increment: totals.wht }, totalPension: { increment: totals.pension }, totalEmployerPension: { increment: totals.employerPension }, totalNhf: { increment: totals.nhf }, totalLoans: { increment: totals.loans }, totalOtherDeductions: { increment: totals.other }, totalPermanentNetPay: { increment: totals.permanentNet }, totalExternalNetPay: { increment: totals.externalNet }, totalNetPay: { increment: totals.net }, processingHeartbeatAt: new Date() } });
        return { employees: totals.participants };
      }
      const totals = await computeEmployeePayslips(tx, batch.organizationId, batch.payrollRun, currency, employeeIds);
      const completed = await tx.payrollCalculationBatch.updateMany({ where: { id: batch.id, status: "PROCESSING" }, data: { status: "COMPLETED", processedCount: totals.employees, failedCount: 0, totals: { gross: totals.totals.gross.toString(), paye: totals.totals.paye.toString(), pension: totals.totals.pension.toString(), employerPension: totals.totals.employerPension.toString(), nhf: totals.totals.nhf.toString(), loans: totals.totals.loans.toString(), other: totals.totals.other.toString(), net: totals.totals.net.toString() }, completedAt: new Date() } });
      if (completed.count) await tx.payrollRun.update({ where: { id: batch.payrollRunId }, data: { processedEmployeeCount: { increment: totals.employees }, totalGross: { increment: totals.totals.gross }, totalPaye: { increment: totals.totals.paye }, totalPension: { increment: totals.totals.pension }, totalEmployerPension: { increment: totals.totals.employerPension }, totalNhf: { increment: totals.totals.nhf }, totalLoans: { increment: totals.totals.loans }, totalOtherDeductions: { increment: totals.totals.other }, totalNetPay: { increment: totals.totals.net }, processingHeartbeatAt: new Date() } });
      return totals;
    }, { maxWait: 10_000, timeout: 60_000 });
    const remaining = await prisma.payrollCalculationBatch.count({ where: { payrollRunId: batch.payrollRunId, status: { not: "COMPLETED" } } });
    if (!remaining && unified) await reconcileUnifiedPayRunCompletion(batch.payrollRunId);
    else if (!remaining) await prisma.payrollRun.updateMany({ where: { id: batch.payrollRunId, status: "PROCESSING", processedEmployeeCount: { equals: batch.payrollRun.expectedEmployeeCount } }, data: { status: "PENDING_APPROVAL", computedAt: new Date(), failureReason: null } });
    return { processed: computed.employees };
  } catch (error) {
    await prisma.payrollCalculationBatch.updateMany({ where: { id: batchId, status: "PROCESSING" }, data: { status: "PENDING", errorMessage: error instanceof Error ? error.message.slice(0, 2000) : "Payroll batch failed" } });
    throw error;
  }
};

export const failPayRunBatch = async (batchId: string, error: Error) => {
  const batch = await prisma.payrollCalculationBatch.findUnique({ where: { id: batchId }, include: { payrollRun: true } }); if (!batch || batch.status === "COMPLETED") return;
  await prisma.$transaction(async (tx) => { await tx.payrollCalculationBatch.update({ where: { id: batch.id }, data: { status: "FAILED", failedCount: batch.expectedCount, errorMessage: error.message.slice(0, 2000) } }); await tx.payrollRun.update({ where: { id: batch.payrollRunId }, data: batch.payrollRun.membershipVersion === "UNIFIED_PAYEE_V1" ? { status: "FAILED", failedParticipantCount: { increment: batch.expectedCount }, failureReason: "One or more payroll calculation batches failed" } : { status: "FAILED", failedEmployeeCount: { increment: batch.expectedCount }, failureReason: "One or more payroll calculation batches failed" } }); if (batch.payrollRun.membershipVersion === "UNIFIED_PAYEE_V1") { const input = jsonRecord(batch.payrollRun.calculationInput); await createAuditLog({ organizationId: batch.organizationId, actorUserId: typeof input.requestedById === "string" ? input.requestedById : undefined, action: "PAYROLL_RUN_PROCESSING_FAILED", resource: "PAYROLL_RUN", resourceId: batch.payrollRunId, summary: "Frozen unified payroll calculation failed", metadata: { batchId: batch.id, failedParticipantCount: batch.expectedCount, previousStatus: "PROCESSING", newStatus: "FAILED" } }, tx); } });
};

export const reconcileProcessingPayRuns = async (options: { execution?: "queue" | "direct"; runLimit?: number; batchLimit?: number } = {}) => {
  const stale = new Date(Date.now() - 5 * 60_000);
  await prisma.payrollCalculationBatch.updateMany({ where: { status: "PROCESSING", updatedAt: { lt: stale } }, data: { status: "PENDING", errorMessage: "Recovered after an interrupted worker" } });
  const runs = await prisma.payrollRun.findMany({ where: { status: "PROCESSING" }, orderBy: { updatedAt: "asc" }, take: options.runLimit ?? 20, select: { id: true } });
  if (options.execution === "direct") {
    for (const run of runs) await initializePayRunCalculation(run.id, { execution: "direct", batchLimit: options.batchLimit ?? 5 });
  } else {
    await Promise.all(runs.map((run) => enqueuePayrollJob("initialize-pay-run", { payrollRunId: run.id }, `payroll-recover-${run.id}-${Math.floor(Date.now() / 300_000)}`)));
  }
  return { recoveredRuns: runs.length };
};

export const runPayrollProcessingCron = () => reconcileProcessingPayRuns({ execution: "direct", runLimit: env.PAYROLL_CRON_RUN_LIMIT, batchLimit: env.PAYROLL_CRON_BATCH_LIMIT });
