export const approvePayRun = async (organizationId: string, payRunId: string, user: AuthUser) => { const now = new Date(); const result = await prisma.$transaction(async (tx) => { await tx.$queryRaw`SELECT id FROM PayrollRun WHERE id = ${payRunId} AND organizationId = ${organizationId} FOR UPDATE`; const current = await tx.payrollRun.findFirst({ where: { id: payRunId, organizationId } }); if (!current) throw notFound("Payroll run not found"); if (current.status === "APPROVED") return current; const updated = await tx.payrollRun.updateMany({ where: { id: payRunId, organizationId, status: "PENDING_APPROVAL" }, data: { status: "APPROVED", approvedAt: now, approvedById: user.id } }); if (!updated.count) throw conflict(`Payroll run cannot be approved from ${current.status}`); await tx.payrollAdjustmentApplication.updateMany({ where: { organizationId, payrollRunId: payRunId, status: "APPLIED" }, data: { status: "ACCEPTED" } }); const row = await tx.payrollRun.findUniqueOrThrow({ where: { id: payRunId } }); await createAuditLog({ organizationId, actorUserId: user.id, action: "PAYROLL_APPROVED", resource: "PAYROLL_RUN", resourceId: payRunId, summary: `Approved payroll ${row.name} for the next operational stage`, metadata: { previousStatus: "PENDING_APPROVAL", newStatus: "APPROVED", paymentOrSettlementCreated: false } }, tx); return row; }, { isolationLevel: Prisma.TransactionIsolationLevel.RepeatableRead }); return payRunDto(result, true); };
