const finalizedTaxSlips = (organizationId: string, year: number) => prisma.payslip.findMany({ where: { organizationId, payrollrun: { status: { in: [...payrollReportableStatuses] }, periodStart: { gte: new Date(Date.UTC(year, 0, 1)), lt: new Date(Date.UTC(year + 1, 0, 1)) } } }, include: { payrollrun: { select: { periodStart: true } } } });
const taxRows = async (organizationId: string, year: number, period?: string) => { const slips = await finalizedTaxSlips(organizationId, year); const currentPeriod = period ?? `${year}-${String(new Date().getUTCMonth() + 1).padStart(2, "0")}`; const rows = new Map<string, any>(); for (const slip of slips) { const row = rows.get(slip.employeeId) ?? { employee: { id: slip.employeeId, employeeId: slip.employeeNoSnapshot, fullName: slip.employeeNameSnapshot, role: slip.roleSnapshot }, department: { id: slip.departmentIdSnapshot, name: slip.departmentNameSnapshot }, tin: slip.tinSnapshot ? `***${slip.tinSnapshot.slice(-4)}` : null, state: slip.taxStateSnapshot ?? "UNCONFIGURED", authority: jsonRecord(slip.taxAuthoritySnapshot), currentGross: zeroDecimal(), currentPaye: zeroDecimal(), ytdGross: zeroDecimal(), ytdPaye: zeroDecimal() }; row.ytdGross = row.ytdGross.add(slip.grossPay); row.ytdPaye = row.ytdPaye.add(slip.payeTax); if (slip.payrollrun.periodStart.toISOString().slice(0, 7) === currentPeriod) { row.currentGross = row.currentGross.add(slip.grossPay); row.currentPaye = row.currentPaye.add(slip.payeTax); } rows.set(slip.employeeId, row); } return [...rows.values()].map((row) => ({ employee: row.employee, department: row.department, tin: row.tin, state: { code: row.state, name: row.state }, authority: { code: row.authority.code ?? null, name: row.authority.name ?? null, configured: Boolean(row.authority.configured) }, currentPeriod: { gross: Number(row.currentGross), paye: Number(row.currentPaye) }, ytd: { gross: Number(row.ytdGross), paye: Number(row.ytdPaye) }, effectiveRate: row.ytdGross.isZero() ? 0 : Number(row.ytdPaye.div(row.ytdGross).mul(100).toDecimalPlaces(2)) })); };
export const getPayrollTaxOverview = async (organizationId: string, query: any) => { await synchronizePayeRemittances(organizationId); const rows = await taxRows(organizationId, query.year, query.period); const remittances = await prisma.payrollTaxRemittance.findMany({ where: { organizationId, period: { startsWith: String(query.year) } } }); const authorities = new Set(rows.map((row) => row.authority.code ?? `STATE:${row.state.code}`)); const ytdPaye = rows.reduce((sum, row) => sum.add(row.ytd.paye), zeroDecimal()); const ytdRemitted = remittances.filter((row) => row.status === "REMITTED").reduce((sum, row) => sum.add(row.amount), zeroDecimal()); const nextDue = remittances.filter((row) => row.status !== "REMITTED" && row.dueDate && row.dueDate >= new Date()).sort((a, b) => a.dueDate!.getTime() - b.dueDate!.getTime())[0]?.dueDate ?? null; return { stateAuthorities: authorities.size, ytdPayeDeducted: Number(ytdPaye), ytdRemitted: Number(ytdRemitted), nextDueDate: nextDue, currency: "NGN" }; };
export const getPayrollTaxEmployeesByState = async (organizationId: string, query: any) => { let rows = await taxRows(organizationId, query.year, query.period); if (query.search) { const term = query.search.toLowerCase(); rows = rows.filter((row) => `${row.employee.fullName} ${row.employee.employeeId}`.toLowerCase().includes(term)); } if (query.state) rows = rows.filter((row) => row.state.code.toLowerCase() === query.state.toLowerCase()); if (query.authority) rows = rows.filter((row) => String(row.authority.code ?? "").toLowerCase() === query.authority.toLowerCase()); const total = rows.length; const items = rows.slice((query.page - 1) * query.limit, query.page * query.limit); const groups = new Map<string, any>(); for (const row of rows) { const key = row.authority.code ?? `STATE:${row.state.code}`; const group = groups.get(key) ?? { state: row.state, authority: row.authority, employeeCount: 0, currentPeriodPaye: zeroDecimal() }; group.employeeCount += 1; group.currentPeriodPaye = group.currentPeriodPaye.add(row.currentPeriod.paye); groups.set(key, group); } return { groups: [...groups.values()].map((group) => ({ ...group, currentPeriodPaye: Number(group.currentPeriodPaye) })), employees: items, pagination: payeePagination(query.page, query.limit, total) }; };
export const listPayrollTaxRemittances = async (organizationId: string, query: any) => { await synchronizePayeRemittances(organizationId); const now = new Date(); const where: Prisma.PayrollTaxRemittanceWhereInput = { organizationId, period: { startsWith: String(query.year) }, ...(query.period ? { period: query.period } : {}), ...(query.status === "REMITTED" ? { status: "REMITTED" } : query.status === "DUE" ? { status: { not: "REMITTED" }, OR: [{ dueDate: null }, { dueDate: { gte: now } }] } : query.status === "OVERDUE" ? { status: { not: "REMITTED" }, dueDate: { lt: now } } : {}) }; const [rows, total] = await Promise.all([prisma.payrollTaxRemittance.findMany({ where, orderBy: [{ period: "desc" }, { state: "asc" }], skip: (query.page - 1) * query.limit, take: query.limit }), prisma.payrollTaxRemittance.count({ where })]); return { remittances: rows.map((row) => ({ id: row.id, period: row.period, state: row.state, authority: { code: row.authorityCode, name: row.authorityName }, employees: row.employeeCount, payeAmount: Number(row.amount), dueDate: row.dueDate, status: row.status === "REMITTED" ? "REMITTED" : row.dueDate && row.dueDate < now ? "OVERDUE" : "DUE", remittedAt: row.remittedAt, paymentReference: row.paymentReference, receiptAvailable: Boolean(row.receiptReference) })), pagination: payeePagination(query.page, query.limit, total) }; };
export const getPayrollTaxAnnualReturns = async (organizationId: string, query: any) => { let rows = await taxRows(organizationId, query.year); if (query.search) rows = rows.filter((row) => `${row.employee.fullName} ${row.employee.employeeId}`.toLowerCase().includes(query.search.toLowerCase())); if (query.state) rows = rows.filter((row) => row.state.code.toLowerCase() === query.state.toLowerCase()); const total = rows.length; return { year: query.year, rows: rows.slice((query.page - 1) * query.limit, query.page * query.limit), pagination: payeePagination(query.page, query.limit, total) }; };
const taxEmployeeRowsPaged=async(organizationId:string,query:any)=>{const from=new Date(Date.UTC(query.year,0,1));const to=new Date(Date.UTC(query.year+1,0,1));const current=query.period??`${query.year}-${String(new Date().getUTCMonth()+1).padStart(2,"0")}`;const search=query.search?`%${query.search}%`:null;const filters=Prisma.sql`${search?Prisma.sql` AND (p.employeeNameSnapshot LIKE ${search} OR p.employeeNoSnapshot LIKE ${search})`:Prisma.empty}${query.state?Prisma.sql` AND p.taxStateSnapshot=${query.state}`:Prisma.empty}${query.authority?Prisma.sql` AND JSON_UNQUOTE(JSON_EXTRACT(p.taxAuthoritySnapshot,'$.code'))=${query.authority}`:Prisma.empty}`;const base=Prisma.sql`FROM Payslip p JOIN PayrollRun pr ON pr.id=p.payrollRunId AND pr.organizationId=p.organizationId WHERE p.organizationId=${organizationId} AND ${reportableRunSql} AND pr.periodStart>=${from} AND pr.periodStart<${to} ${filters}`;const offset=(query.page-1)*query.limit;const [rows,counts]=await Promise.all([prisma.$queryRaw<Array<{employeeId:string;employeeNo:string|null;employeeName:string|null;roleName:string|null;departmentId:string|null;departmentName:string|null;tin:string|null;stateName:string|null;authority:unknown;currentGross:Prisma.Decimal;currentPaye:Prisma.Decimal;ytdGross:Prisma.Decimal;ytdPaye:Prisma.Decimal}>>(Prisma.sql`SELECT p.employeeId,MAX(p.employeeNoSnapshot) employeeNo,MAX(p.employeeNameSnapshot) employeeName,MAX(p.roleSnapshot) roleName,MAX(p.departmentIdSnapshot) departmentId,MAX(p.departmentNameSnapshot) departmentName,MAX(p.tinSnapshot) tin,MAX(p.taxStateSnapshot) stateName,MAX(p.taxAuthoritySnapshot) authority,SUM(CASE WHEN DATE_FORMAT(pr.periodStart,'%Y-%m')=${current} THEN p.grossPay ELSE 0 END) currentGross,SUM(CASE WHEN DATE_FORMAT(pr.periodStart,'%Y-%m')=${current} THEN p.payeTax ELSE 0 END) currentPaye,SUM(p.grossPay) ytdGross,SUM(p.payeTax) ytdPaye ${base} GROUP BY p.employeeId ORDER BY employeeName ASC LIMIT ${query.limit} OFFSET ${offset}`),prisma.$queryRaw<Array<{total:bigint}>>(Prisma.sql`SELECT COUNT(*) total FROM (SELECT 1 ${base} GROUP BY p.employeeId) grouped`)]);return{rows:rows.map(row=>{const authority=jsonRecord(row.authority as any);const ytdGross=new Prisma.Decimal(row.ytdGross);const ytdPaye=new Prisma.Decimal(row.ytdPaye);const state=row.stateName??"UNCONFIGURED";return{employee:{id:row.employeeId,employeeId:row.employeeNo,fullName:row.employeeName,role:row.roleName},department:{id:row.departmentId,name:row.departmentName},tin:row.tin?`***${row.tin.slice(-4)}`:null,state:{code:state,name:state},authority:{code:authority.code??null,name:authority.name??null,configured:Boolean(authority.configured)},currentPeriod:{gross:Number(row.currentGross),paye:Number(row.currentPaye)},ytd:{gross:Number(ytdGross),paye:Number(ytdPaye)},effectiveRate:ytdGross.isZero()?0:Number(ytdPaye.div(ytdGross).mul(100).toDecimalPlaces(2))}}),total:Number(counts[0]?.total??0)}};
export const getPayrollTaxEmployeesByStatePaged=async(organizationId:string,query:any)=>{const result=await taxEmployeeRowsPaged(organizationId,query);const groups=await prisma.$queryRaw<Array<{stateName:string|null;authorityCode:string|null;authorityName:string|null;employeeCount:bigint;currentPeriodPaye:Prisma.Decimal}>>(Prisma.sql`SELECT p.taxStateSnapshot stateName,JSON_UNQUOTE(JSON_EXTRACT(p.taxAuthoritySnapshot,'$.code')) authorityCode,JSON_UNQUOTE(JSON_EXTRACT(p.taxAuthoritySnapshot,'$.name')) authorityName,COUNT(DISTINCT p.employeeId) employeeCount,SUM(CASE WHEN DATE_FORMAT(pr.periodStart,'%Y-%m')=${query.period??`${query.year}-${String(new Date().getUTCMonth()+1).padStart(2,"0")}`} THEN p.payeTax ELSE 0 END) currentPeriodPaye FROM Payslip p JOIN PayrollRun pr ON pr.id=p.payrollRunId AND pr.organizationId=p.organizationId WHERE p.organizationId=${organizationId} AND ${reportableRunSql} AND pr.periodStart>=${new Date(Date.UTC(query.year,0,1))} AND pr.periodStart<${new Date(Date.UTC(query.year+1,0,1))} GROUP BY p.taxStateSnapshot,authorityCode,authorityName`);return{groups:groups.map(row=>({state:{code:row.stateName??"UNCONFIGURED",name:row.stateName??"UNCONFIGURED"},authority:{code:row.authorityCode,name:row.authorityName,configured:Boolean(row.authorityCode)},employeeCount:Number(row.employeeCount),currentPeriodPaye:Number(row.currentPeriodPaye)})),employees:result.rows,pagination:payeePagination(query.page,query.limit,result.total)}};
export const getPayrollTaxAnnualReturnsPaged=async(organizationId:string,query:any)=>{const result=await taxEmployeeRowsPaged(organizationId,{...query,period:undefined,authority:undefined});return{year:query.year,rows:result.rows,pagination:payeePagination(query.page,query.limit,result.total)}};
export const getPayrollTaxOverviewPaged=async(organizationId:string,query:any)=>{const from=new Date(Date.UTC(query.year,0,1));const to=new Date(Date.UTC(query.year+1,0,1));const rows=await prisma.$queryRaw<Array<{authorities:bigint;ytdPaye:Prisma.Decimal}>>(Prisma.sql`SELECT COUNT(DISTINCT COALESCE(JSON_UNQUOTE(JSON_EXTRACT(p.taxAuthoritySnapshot,'$.code')),CONCAT('STATE:',COALESCE(p.taxStateSnapshot,'UNCONFIGURED')))) authorities,COALESCE(SUM(p.payeTax),0) ytdPaye FROM Payslip p JOIN PayrollRun pr ON pr.id=p.payrollRunId AND pr.organizationId=p.organizationId WHERE p.organizationId=${organizationId} AND ${reportableRunSql} AND pr.periodStart>=${from} AND pr.periodStart<${to}`);const [remitted,next]=await Promise.all([prisma.payrollTaxRemittance.aggregate({where:{organizationId,period:{startsWith:String(query.year)},status:"REMITTED"},_sum:{amount:true}}),prisma.payrollTaxRemittance.findFirst({where:{organizationId,period:{startsWith:String(query.year)},status:{not:"REMITTED"},dueDate:{gte:new Date()}},orderBy:{dueDate:"asc"},select:{dueDate:true}})]);return{stateAuthorities:Number(rows[0]?.authorities??0),ytdPayeDeducted:Number(rows[0]?.ytdPaye??0),ytdRemitted:Number(remitted._sum.amount??0),nextDueDate:next?.dueDate??null,currency:"NGN"}};
