export const downloadPayrollTaxReceipt = async (organizationId: string, id: string) => { const row = await prisma.payrollTaxRemittance.findFirst({ where: { id, organizationId, status: "REMITTED" } }); if (!row?.receiptReference) throw notFound("Remittance receipt is not available"); const content = [`PAYE REMITTANCE RECEIPT`, `Period: ${row.period}`, `State: ${row.state}`, `Authority: ${row.authorityName ?? row.authorityCode}`, `Amount: ${row.amount.toFixed(2)}`, `Reference: ${row.paymentReference}`, `Remitted: ${row.remittedAt?.toISOString()}`].join("\n"); return { filename: `paye-remittance-${row.period}-${row.id}.txt`, buffer: Buffer.from(content, "utf8") }; };

const pensionConfig = async (organizationId: string) => { const row = await prisma.systemConfig.findUnique({ where: { organizationId_key: { organizationId, key: "payroll.pension.config" } }, select: { value: true } }); return jsonRecord(row?.value); };
const pensionDueDate = (period: string, dueDay: number | null) => { if (dueDay === null) return null; const [year, month] = period.split("-").map(Number); return new Date(Date.UTC(year, month, Math.min(Math.max(dueDay, 1), 28), 23, 59, 59, 999)); };
